@isTest private class CurrentBaseMessagingRenderTemplateDtoTest {
 @isTest static void dtoFieldsAndMethodsWitness() {
  Messaging.RenderEmailTemplateBodyResult body = new Messaging.RenderEmailTemplateBodyResult();
  Messaging.RenderEmailTemplateError error = new Messaging.RenderEmailTemplateError();
  System.assertEquals(0, body.errors.size());
  System.assertEquals(null, body.mergedbody);
  System.assertEquals(null, body.success);
  System.assertEquals(null, error.fieldname);
  System.assertEquals(null, error.message);
  System.assertEquals(null, error.offset);
  System.assertEquals(null, error.statuscode);
  System.assertEquals(true, body.equals(body));
  System.assertEquals(true, error.equals(error));
  Object bodyHash = body.hashCode();
  Object errorHash = error.hashCode();
  Object bodyText = body.toString();
  Object errorText = error.toString();
  System.assertNotEquals(null, bodyHash);
  System.assertNotEquals(null, errorHash);
  System.assertNotEquals(null, bodyText);
  System.assertNotEquals(null, errorText);
 }
}
